import subprocess,os,hashlib
q="SELECT m.id meeting_id,m.owner_id,i.status,i.session_generation identity_generation,s.session_generation session_generation,s.issued_at,s.expires_at,s.revoked_at,f.created_at file_created_at,UTC_TIMESTAMP(6) observed_now FROM file_object f JOIN meeting m ON m.id=f.meeting_id JOIN enterprise_identity i ON i.enterprise_id=m.owner_id JOIN identity_session s ON s.enterprise_id=m.owner_id WHERE f.sha256='"+hashlib.sha256(b'sequence first\n').hexdigest()+"' ORDER BY f.created_at DESC LIMIT 10"
r=subprocess.run(['docker','exec','-e','MYSQL_PWD','ama-test-b01-ad9f1af29eff','mysql','-u',os.environ['AMA_TEST_DATABASE_USERNAME'],'--database=ama_b01_fixture','--batch','--raw','-e',q],capture_output=True,text=True);assert r.returncode==0;print(r.stdout)
